import { atom, read, update } from 'claude-code'
import type { EngineInterface, Register, ThemeKey } from 'claude-code'

import { layout } from './band'
import type { Tone } from './band'
import { add, run } from './command'
import type { Outcome } from './command'
import { EMPTY, filePath, parse } from './deadlines'
import { settingsOf } from './settings'
import type { Settings } from './settings'
import { brief, nudge, readToasted, thresholds } from './smart'

const REFRESH_MS = 60_000
const DAY_MS = 24 * 60 * 60_000

// Theme keys, so the band follows the person's theme, light or dark.
const COLOR: Record<Tone, ThemeKey> = {
  calm: 'success',
  soon: 'warning',
  urgent: 'error',
  overdue: 'error',
}

const ID = { type: 'string', description: "The deadline's id, or its start." }

const loaded = atom({ plugin: 'due-band', key: 'loaded' } as const, EMPTY)
const now = atom({ plugin: 'due-band', key: 'now' } as const, 0)
const isHidden = atom({ plugin: 'due-band', key: 'isHidden' } as const, false)
const cwd = atom({ plugin: 'due-band', key: 'cwd' } as const, '')
const nudged = atom({ plugin: 'due-band', key: 'nudged' } as const, '')

const pathOf = async ($: EngineInterface, { file }: Settings) =>
  filePath((await $.env.get('USERPROFILE')) ?? (await $.env.get('HOME')), file)

const textOf = (value: unknown) => (typeof value === 'string' ? value : '')

// What Claude reads when one of the tools fails: nothing was written.
const failed = () => ({ deny: 'due-band could not update due.json.' })

// Reads the file again each time, so an edit by hand shows within a minute.
// A missing file is no deadlines, not an error.
const refresh = async ($: EngineInterface, settings: Settings) => {
  const text = await $.fs.read(await pathOf($, settings)).catch(() => null)
  const at = await $.clock.now()
  const here = await $.session.cwd().catch(() => '')
  const { deadlines } = text === null ? EMPTY : parse(text)

  await update($, loaded, () => (text === null ? EMPTY : parse(text)))
  await update($, now, () => at)
  await update($, cwd, () => here)

  // Each threshold a deadline crosses is said once, across sessions.
  const before = readToasted(await $.store.get('toasted').catch(() => null))
  const { toasts, seen } = thresholds(deadlines, at, before)

  if (JSON.stringify(seen) !== JSON.stringify(before)) {
    await $.store.set('toasted', seen).catch(() => undefined)
  }

  // The wrong-project line stays in the band while it holds; the toast is once.
  const line = nudge(deadlines, at, here, settings.nudgeDays * DAY_MS)

  if (line !== null && line !== (await read($, nudged))) {
    toasts.push(line)
    await update($, nudged, () => line)
  }

  if (settings.toasts && toasts.length > 0) {
    $.ui.toast(toasts.join('\n'), { timeoutMs: 8000 })
  }
}

// One run of the command or of a tool: reads the file, writes what changed.
const apply = async (
  $: EngineInterface,
  settings: Settings,
  change: (text: string | null, at: number) => Outcome,
) => {
  const path = await pathOf($, settings)
  const text = await $.fs.read(path).catch(() => null)
  const outcome = change(text, await $.clock.now())

  if (outcome.file !== null) {
    await $.fs.write(path, outcome.file)
    await refresh($, settings)
  }

  return outcome
}

export const register: Register = (on, options) => {
  const settings = settingsOf(options)

  on('session.start', async ($, e, next) => {
    await $.command.register({
      name: 'due',
      description: 'Add, update and close deadlines shown above the prompt',
      argumentHint: 'add | next | done | here | rm | list | hide | show',
    })
    if (settings.tellClaude) {
      await $.tool.register({
        name: 'set_next_step',
        description:
          "Set the next step of one of the person's deadlines, shown above their prompt. Use it when they finish a step or say what comes next.",
        inputSchema: {
          type: 'object',
          properties: {
            id: ID,
            next: { type: 'string', description: 'The next step, one line.' },
          },
          required: ['id', 'next'],
        },
        isDeferred: false,
      })
      await $.tool.register({
        name: 'mark_done',
        description:
          "Close one of the person's deadlines once they say it is delivered or no longer needed.",
        inputSchema: {
          type: 'object',
          properties: { id: ID },
          required: ['id'],
        },
        isDeferred: false,
      })
      await $.tool.register({
        name: 'add_deadline',
        description:
          'Add a deadline the person mentions ("the deck is due Friday") to the list shown above their prompt.',
        inputSchema: {
          type: 'object',
          properties: {
            name: { type: 'string', description: 'A short name: "Fez deck".' },
            due: {
              type: 'string',
              description:
                'When it is due: 2026-10-21, 2026-10-21 18:00, 21 oct, +9d, fri, today or tomorrow.',
            },
            next: { type: 'string', description: 'The next step, if known.' },
          },
          required: ['name', 'due'],
        },
        isDeferred: false,
      })
    }

    await refresh($, settings)
    $.clock.every(REFRESH_MS, () => void refresh($, settings))

    return next(e)
  })

  on('command.run', { command: 'due' }, async ($, e) => {
    const here = await $.session.cwd().catch(() => '')
    const outcome = await apply($, settings, (text, at) =>
      run(e.args, text, at, here),
    )

    if (outcome.isHidden !== null) {
      const next = outcome.isHidden
      await update($, isHidden, () => next)
    }

    return { text: outcome.text }
  })

  on('tool.call', { tool: 'mcp__due-band__set_next_step' }, async ($, e) => {
    const args = `next ${textOf(e.id)} ${textOf(e.next)}`

    const outcome = await apply($, settings, (text, at) => run(args, text, at))

    return { result: outcome.text }
  }).catch(failed)

  on('tool.call', { tool: 'mcp__due-band__mark_done' }, async ($, e) => {
    const args = `done ${textOf(e.id)}`

    const outcome = await apply($, settings, (text, at) => run(args, text, at))

    return { result: outcome.text }
  }).catch(failed)

  on('tool.call', { tool: 'mcp__due-band__add_deadline' }, async ($, e) => {
    const outcome = await apply($, settings, (text, at) =>
      add(textOf(e.name), textOf(e.due), textOf(e.next), text, at),
    )

    return { result: outcome.text }
  }).catch(failed)

  on('prompt.compose', async ($, e, next) => {
    const composed = await next(e)
    const { deadlines } = await read($, loaded)
    const text = settings.tellClaude
      ? brief(deadlines, await read($, now), await read($, cwd))
      : null

    return text === null
      ? composed
      : {
          sections: [
            ...composed.sections,
            { id: 'due-band:deadlines', text, scope: 'session' as const },
          ],
        }
  })

  on('ui.render', { component: 'AbovePrompt' }, async ($, e, next) => {
    const { deadlines, error } = await read($, loaded)
    const at = await read($, now)
    const here = await read($, cwd)
    const band = layout(deadlines, at, e.props.bodyColumns, {
      marks: settings.marks,
      cwd: here,
      maxRows: settings.maxRows,
      nudgeMs: settings.nudgeDays * DAY_MS,
    })
    const isQuiet =
      e.props.hasSurvey ||
      (await read($, isHidden)) ||
      (error === null && band.rows.length === 0)

    if (isQuiet) {
      return next(e)
    }

    const { Box, Text } = $.ui.resolve(e)

    if (error !== null) {
      return (
        <Box>
          <Text dimColor>due.json: {error}</Text>
        </Box>
      )
    }

    const more = band.more === 0 ? '' : `+${band.more} more`

    if (band.isSummary) {
      return (
        <Box>
          <Text wrap="truncate-end">
            {band.rows.map((row, index) => (
              <Text>
                <Text dimColor>{index === 0 ? '' : ' · '}</Text>
                <Text bold={row.isHere}>{row.name}</Text>{' '}
                <Text color={COLOR[row.tone]} bold>
                  {row.left}
                </Text>
              </Text>
            ))}
            <Text dimColor>{more === '' ? '' : ` · ${more}`}</Text>
          </Text>
        </Box>
      )
    }

    return (
      <Box flexDirection="column">
        {band.rows.map(row => (
          <Text wrap="truncate-end">
            <Text color={COLOR[row.tone]} bold={row.tone === 'overdue'}>
              {row.mark}
            </Text>{' '}
            <Text bold={row.isHere}>{row.name}</Text>
            {'  '}
            <Text dimColor>{row.spent}</Text>
            <Text color={COLOR[row.tone]}>{row.ahead}</Text>
            {'  '}
            <Text color={COLOR[row.tone]} bold>
              {row.left}
            </Text>
            <Text dimColor>{row.next === '' ? '' : `  ${row.next}`}</Text>
          </Text>
        ))}
        {more !== '' && <Text dimColor>{`  ${more}`}</Text>}
        {band.nudge !== null && (
          <Text color="warning" wrap="truncate-end">
            {band.nudge}
          </Text>
        )}
      </Box>
    )
  })
}

