import type { Deadline } from '../types'

import { open, timeLeft } from './deadlines'
import { isInside, nudge, NUDGE_MS } from './smart'

const DAY = 24 * 60 * 60_000

/** Below this many cells the band is one line of names and times. */
const NARROW = 40

/** How close a deadline is: 7 days and up, 3 to 7, under 3, and past. */
export type Tone = 'calm' | 'soon' | 'urgent' | 'overdue'

/** What leads a row: a face for how the time left feels, or a plain mark. */
export type Marks = 'emoji' | 'plain'

// Each set is one width throughout, so the names after it line up: an emoji
// takes two cells, and is two units long in a string as well.
const MARK: Record<Marks, Record<Tone, string>> = {
  emoji: { calm: '😌', soon: '👀', urgent: '🔥', overdue: '💀' },
  plain: { calm: '•', soon: '•', urgent: '•', overdue: '!' },
}

/**
 * One deadline as the band draws it, every part already cut and padded to
 * its column: the drawing only picks colors.
 */
export type Row = {
  id: string
  tone: Tone
  mark: string
  name: string
  spent: string
  ahead: string
  left: string
  next: string
  /** The session's folder is one of this deadline's `paths`. */
  isHere: boolean
}

/** What the person's settings and the session decide about the band. */
export type Look = {
  marks: Marks
  /** The session's working folder; `''` when it is not known. */
  cwd: string
  /** How many deadlines are listed before `+N more`. */
  maxRows: number
  /** How near a deadline is before working elsewhere is said; 0 for never. */
  nudgeMs: number
}

export const LOOK: Look = {
  marks: 'emoji',
  cwd: '',
  maxRows: 3,
  nudgeMs: NUDGE_MS,
}

/**
 * The band: its rows, whether they share one line, how many are left out,
 * and the line for working somewhere else while one of them is close.
 */
export type Band = {
  rows: Row[]
  isSummary: boolean
  more: number
  nudge: string | null
}

export function tone(dueAt: number, now: number): Tone {
  const left = dueAt - now

  return left < 0
    ? 'overdue'
    : left < 3 * DAY
      ? 'urgent'
      : left < 7 * DAY
        ? 'soon'
        : 'calm'
}

/** `text` in at most `width` cells, its end traded for `…` when it is longer. */
export function cut(text: string, width: number): string {
  return text.length <= width
    ? text
    : width <= 1
      ? text.slice(0, Math.max(0, width))
      : `${text.slice(0, width - 1).trimEnd()}…`
}

/**
 * The bar is a fuse burning from the left: this is how many of its cells are
 * burnt, the share of the way from `start` to `due`. Only a deadline that is
 * past has none left; `null` when there is no `start` to measure from.
 */
function burnt(one: Deadline, now: number, width: number): number | null {
  if (now > one.dueAt) {
    return width
  }

  if (one.startAt === null || one.startAt >= one.dueAt) {
    return null
  }

  const share = (now - one.startAt) / (one.dueAt - one.startAt)
  const cells = Math.round(share * width)

  return share <= 0 ? 0 : Math.min(width - 1, Math.max(1, cells))
}

/** One line for a narrow column: `Atlas demo 7d · Reel clips 9d · +1 more`. */
function summary(
  all: Deadline[],
  now: number,
  columns: number,
  { marks, cwd, maxRows }: Look,
): Band {
  const rows: Row[] = []
  let used = 0

  for (const one of all.slice(0, maxRows)) {
    const left = timeLeft(one.dueAt, now)
    const after = all.length - rows.length - 1
    const tail = after > 0 ? ` · +${after} more`.length : 0
    const gap = rows.length === 0 ? 0 : 3
    const room = columns - used - gap - tail - left.length - 1
    const isFirst = rows.length === 0

    if (!isFirst && room < one.name.length) {
      break
    }

    const name = cut(one.name, Math.max(1, room))
    const kind = tone(one.dueAt, now)

    used += gap + name.length + 1 + left.length
    rows.push({
      id: one.id,
      tone: kind,
      mark: MARK[marks][kind],
      name,
      spent: '',
      ahead: '',
      left,
      next: '',
      isHere: isInside(one.paths, cwd),
    })
  }

  return { rows, isSummary: true, more: all.length - rows.length, nudge: null }
}

/**
 * Lays the open deadlines out in `columns` cells, soonest first: full rows
 * with a bar where there is room, one line where there is not.
 */
export function layout(
  deadlines: Deadline[],
  now: number,
  columns: number,
  look: Partial<Look> = {},
): Band {
  const { marks, cwd, maxRows, nudgeMs } = { ...LOOK, ...look }
  const all = open(deadlines)

  if (all.length === 0) {
    return { rows: [], isSummary: false, more: 0, nudge: null }
  }

  if (columns < NARROW) {
    return summary(all, now, columns, { marks, cwd, maxRows, nudgeMs })
  }

  const shown = all.slice(0, maxRows)
  const barWidth = columns >= 100 ? 24 : columns >= 70 ? 16 : 10
  const lefts = shown.map(one => timeLeft(one.dueAt, now))
  const leftWidth = Math.max(...lefts.map(left => left.length))
  const markWidth = MARK[marks].calm.length
  // Mark and name a cell apart, then bar, time and next step two cells apart.
  const fixed = markWidth + 1 + 2 + barWidth + 2 + leftWidth
  const nameWidth = Math.max(
    1,
    Math.min(
      columns >= 70 ? 24 : 14,
      columns - fixed,
      Math.max(...shown.map(one => one.name.length)),
    ),
  )
  const room = columns - fixed - nameWidth - 2

  const rows = shown.map((one, index): Row => {
    const kind = tone(one.dueAt, now)
    const cells = burnt(one, now, barWidth)

    return {
      id: one.id,
      tone: kind,
      mark: MARK[marks][kind],
      name: cut(one.name, nameWidth).padEnd(nameWidth),
      spent: cells === null ? '╌'.repeat(barWidth) : '─'.repeat(cells),
      ahead: cells === null ? '' : '━'.repeat(barWidth - cells),
      left: (lefts[index] ?? '').padStart(leftWidth),
      next: one.next === null || room < 12 ? '' : cut(one.next, room),
      isHere: isInside(one.paths, cwd),
    }
  })
  const line = nudge(deadlines, now, cwd, nudgeMs)

  return {
    rows,
    isSummary: false,
    more: all.length - rows.length,
    nudge: line === null ? null : cut(line, columns),
  }
}

