import type { Deadline } from '../types'

import { open, parse, parseDate, slug, timeLeft } from './deadlines'
import { isInside } from './smart'

/**
 * What one `/due` run comes to: the line to print, the whole new text of
 * due.json when the run changed it, and the band's visibility when it set it.
 */
export type Outcome = {
  text: string
  file: string | null
  isHidden: boolean | null
}

const DAYS = [
  'sunday',
  'monday',
  'tuesday',
  'wednesday',
  'thursday',
  'friday',
  'saturday',
]

const MONTHS = [
  'january',
  'february',
  'march',
  'april',
  'may',
  'june',
  'july',
  'august',
  'september',
  'october',
  'november',
  'december',
]

const DATES = '2026-10-21, 21 oct, +9d or fri'
const USAGE =
  'Expected: /due add | next | done | here | rm | list | hide | show'

const say = (text: string): Outcome => ({ text, file: null, isHidden: null })

const two = (value: number) => String(value).padStart(2, '0')

/** `fri` or `friday` in a list of full names; three letters at least. */
const named = (names: string[], token: string) =>
  token.length < 3 ? -1 : names.findIndex(name => name.startsWith(token))

/** The day a date starts at `tokens[at]`, and how many tokens spell it. */
function readDay(
  tokens: string[],
  at: number,
  now: number,
): { day: Date; used: number } | null {
  const first = (tokens[at] ?? '').toLowerCase()
  const second = (tokens[at + 1] ?? '').toLowerCase()
  const today = new Date(now)
  const ahead = (days: number) =>
    new Date(today.getFullYear(), today.getMonth(), today.getDate() + days)

  if (parseDate(first, true) !== null && first.length === 10) {
    const [year, month, day] = first.split('-').map(Number)

    return { day: new Date(year ?? 0, (month ?? 1) - 1, day ?? 1), used: 1 }
  }

  const offset = /^\+(\d{1,4})d$/.exec(first)

  if (offset !== null) {
    return { day: ahead(Number(offset[1])), used: 1 }
  }

  if (first === 'today' || first === 'tomorrow') {
    return { day: ahead(first === 'today' ? 0 : 1), used: 1 }
  }

  const weekday = named(DAYS, first)

  // The coming one: `fri` typed on a Friday is a week away, `today` is today.
  if (weekday !== -1) {
    return { day: ahead(((weekday - today.getDay() + 6) % 7) + 1), used: 1 }
  }

  const isDayFirst = /^\d{1,2}$/.test(first)
  const month = named(MONTHS, isDayFirst ? second : first)
  const dayText = isDayFirst ? first : second

  if (month === -1 || !/^\d{1,2}$/.test(dayText)) {
    return null
  }

  const inYear = (year: number) => {
    const day = new Date(year, month, Number(dayText))

    return day.getMonth() === month ? day : null
  }
  const thisYear = inYear(today.getFullYear())
  const isPast = thisYear !== null && thisYear.getTime() < ahead(0).getTime()
  const day = isPast ? inYear(today.getFullYear() + 1) : thisYear

  return day === null ? null : { day, used: 2 }
}

/**
 * Reads a date typed at `tokens[at]`, with a time after it when there is one
 * (`21 oct 18:00`), as due.json spells it.
 */
export function readWhen(
  tokens: string[],
  at: number,
  now: number,
): { due: string; used: number } | null {
  const found = readDay(tokens, at, now)

  if (found === null) {
    return null
  }

  const { day, used } = found
  const date = `${day.getFullYear()}-${two(day.getMonth() + 1)}-${two(day.getDate())}`
  const time = /^(\d{1,2}):(\d{2})$/.exec(tokens[at + used] ?? '')
  const due = time === null ? date : `${date} ${two(Number(time[1]))}:${time[2]}`

  if (parseDate(due, true) !== null) {
    return { due, used: time === null ? used : used + 1 }
  }

  return time !== null && parseDate(date, true) !== null ? { due: date, used } : null
}

/** `Wed 21 Oct`, with the year when it is not this one. */
function dayLabel(at: number, now: number): string {
  const day = new Date(at)
  const weekday = (DAYS[day.getDay()] ?? '').slice(0, 3)
  const month = (MONTHS[day.getMonth()] ?? '').slice(0, 3)
  const cap = (word: string) => word.charAt(0).toUpperCase() + word.slice(1)
  const year =
    day.getFullYear() === new Date(now).getFullYear()
      ? ''
      : ` ${day.getFullYear()}`

  return `${cap(weekday)} ${day.getDate()} ${cap(month)}${year}`
}

/** The entry a typed id means: the id itself, or the one id it begins. */
function find(deadlines: Deadline[], typed: string): number | string {
  const key = typed.toLowerCase()
  const exact = deadlines.findIndex(one => one.id.toLowerCase() === key)

  if (exact !== -1) {
    return exact
  }

  const close = deadlines
    .map((one, index) => ({ id: one.id, index }))
    .filter(one => one.id.toLowerCase().startsWith(key))
  const only = close.length === 1 ? close[0] : undefined

  if (only !== undefined) {
    return only.index
  }

  const ids = (close.length > 1 ? close : deadlines).map(one => one.id)

  return close.length > 1
    ? `"${typed}" fits ${ids.join(', ')}. Type more of the id.`
    : ids.length === 0
      ? `No deadline "${typed}"; there are none yet.`
      : `No deadline "${typed}". Ids: ${ids.join(', ')}`
}

function list(deadlines: Deadline[], now: number): string {
  if (deadlines.length === 0) {
    return 'No deadlines. Add one: /due add <name> <date> [next step]'
  }

  const rows = [...open(deadlines), ...deadlines.filter(one => one.isDone)]
  const idWidth = Math.max(...rows.map(one => one.id.length))
  const nameWidth = Math.max(...rows.map(one => one.name.length))

  return rows
    .map(one => {
      const left = one.isDone ? 'done' : timeLeft(one.dueAt, now)
      const when = `${dayLabel(one.dueAt, now)}, ${left}`
      const next = one.next === null || one.isDone ? '' : `  ${one.next}`

      return `${one.id.padEnd(idWidth)}  ${one.name.padEnd(nameWidth)}  ${when}${next}`
    })
    .join('\n')
}

/** due.json as its deadlines and its entries, with the way to write it back. */
type Book = {
  deadlines: Deadline[]
  entries: Record<string, unknown>[]
  save: (line: string, next: Record<string, unknown>[]) => Outcome
}

/** Opens the text of due.json (`null`: no file yet), or says why it cannot. */
function read(text: string | null): Book | { error: string } {
  const { deadlines, error } = parse(text ?? '{"deadlines":[]}')

  if (error !== null) {
    return {
      error: `due.json: ${error}. Fix the file, then run the command again.`,
    }
  }

  // The entries as the file holds them, so a write keeps every field it has,
  // also the ones this mod does not read.
  const data = (text === null ? {} : JSON.parse(text)) as Record<string, unknown>
  const entries = (data.deadlines ?? []) as Record<string, unknown>[]

  return {
    deadlines,
    entries,
    save: (line, next) => ({
      text: line,
      file: `${JSON.stringify({ ...data, deadlines: next }, null, 2)}
`,
      isHidden: null,
    }),
  }
}

/** Adds one deadline under an id no other has, starting today. */
function append(
  book: Book,
  name: string,
  due: string,
  step: string,
  now: number,
): Outcome {
  const base = slug(name) || 'deadline'
  const taken = new Set(book.deadlines.map(one => one.id))
  let id = base

  for (let count = 2; taken.has(id); count += 1) {
    id = `${base}-${count}`
  }

  const entry = {
    id,
    name,
    due,
    start: readWhen(['today'], 0, now)?.due,
    ...(step === '' ? {} : { next: step }),
  }
  const dueAt = parseDate(due, true) ?? now

  return book.save(
    `Added ${name} (${id}), due ${dayLabel(dueAt, now)}, ${timeLeft(dueAt, now)}.`,
    [...book.entries, entry],
  )
}

/**
 * Adds a deadline from its parts, as a tool hands them over: no guessing
 * where the name ends. `when` is anything `/due add` reads as a date.
 */
export function add(
  name: string,
  when: string,
  step: string,
  text: string | null,
  now: number,
): Outcome {
  const book = read(text)
  const tokens = when.trim().split(/\s+/).filter(Boolean)
  const found = readWhen(tokens, 0, now)
  const label = name.trim().replace(/\s+/g, ' ')

  if ('error' in book) {
    return say(book.error)
  }

  if (label === '') {
    return say('A deadline needs a name.')
  }

  if (found === null || found.used !== tokens.length) {
    return say(`"${when}" is not a date. Expected one like ${DATES}`)
  }

  return append(book, label, found.due, step.trim().replace(/\s+/g, ' '), now)
}

/**
 * Runs `/due <args>` against the text of due.json (`null` when there is no
 * file yet) and answers what to print and what to write. It touches nothing
 * itself, so the same call serves the command and its tests.
 */
export function run(
  args: string,
  text: string | null,
  now: number,
  cwd = '',
): Outcome {
  const tokens = args.trim().split(/\s+/).filter(Boolean)
  const verb = (tokens[0] ?? 'list').toLowerCase()

  if (verb === 'hide' || verb === 'show') {
    return {
      text:
        verb === 'hide'
          ? 'Band hidden for this session. /due show brings it back.'
          : 'Band shown.',
      file: null,
      isHidden: verb === 'hide',
    }
  }

  const book = read(text)

  if ('error' in book) {
    return say(book.error)
  }

  const { deadlines, entries, save } = book

  if (verb === 'list') {
    return say(list(deadlines, now))
  }

  if (verb === 'add') {
    for (let at = 2; at < tokens.length; at += 1) {
      const when = readWhen(tokens, at, now)

      if (when !== null) {
        const name = tokens.slice(1, at).join(' ')
        const step = tokens.slice(at + when.used).join(' ')

        return append(book, name, when.due, step, now)
      }
    }

    return say(
      `Expected: /due add <name> <date> [next step], the date like ${DATES}`,
    )
  }

  if (verb !== 'next' && verb !== 'done' && verb !== 'rm' && verb !== 'here') {
    return say(USAGE)
  }

  const typed = tokens[1]

  if (typed === undefined) {
    return say(
      verb === 'next'
        ? 'Expected: /due next <id> <next step>'
        : `Expected: /due ${verb} <id>`,
    )
  }

  const index = find(deadlines, typed)

  if (typeof index === 'string') {
    return say(index)
  }

  const name = deadlines[index]?.name ?? typed

  // Ties the session's folder to the deadline: what the band reads to know
  // whether the person is working on it or somewhere else.
  if (verb === 'here') {
    const paths = deadlines[index]?.paths ?? []

    if (cwd === '') {
      return say('This session has no folder to tie the deadline to.')
    }

    if (isInside(paths, cwd)) {
      return say(`${name} already has this folder.`)
    }

    const folder = cwd.replace(/\\/g, '/')

    return save(
      `${name} is tied to ${folder}.`,
      entries.map((one, at) =>
        at === index ? { ...one, paths: [...paths, folder] } : one,
      ),
    )
  }

  if (verb === 'rm') {
    return save(
      `Removed ${name}.`,
      entries.filter((_, at) => at !== index),
    )
  }

  if (verb === 'done') {
    return save(
      `${name} is done.`,
      entries.map((one, at) => (at === index ? { ...one, done: true } : one)),
    )
  }

  const step = tokens.slice(2).join(' ')

  if (step === '') {
    return say('Expected: /due next <id> <next step>')
  }

  return save(
    `${name}, next: ${step}`,
    entries.map((one, at) => (at === index ? { ...one, next: step } : one)),
  )
}

