import type { PluginOptions } from 'claude-code'

import type { Marks } from './band'

/** The mod's settings as the code reads them: plugin.json's `userConfig`. */
export type Settings = {
  /** Where due.json is; `''` for `.claude/due.json` in the home folder. */
  file: string
  /** How near a deadline is before working elsewhere is said; 0 for never. */
  nudgeDays: number
  /** How many deadlines the band lists before `+N more`. */
  maxRows: number
  /** Whether Claude is told the deadlines and given the tools. */
  tellClaude: boolean
  /** Whether a deadline crossing a threshold raises a toast. */
  toasts: boolean
  marks: Marks
}

export const DEFAULTS: Settings = {
  file: '',
  nudgeDays: 3,
  maxRows: 3,
  tellClaude: true,
  toasts: true,
  marks: 'emoji',
}

const within = (value: unknown, low: number, high: number, or: number) =>
  typeof value === 'number' && Number.isFinite(value)
    ? Math.min(high, Math.max(low, Math.round(value)))
    : or

/** The options the engine hands `register`, each held to what the mod takes. */
export function settingsOf(options: PluginOptions): Settings {
  const { file, nudgeDays, maxRows, tellClaude, toasts, marks } = options

  return {
    file: typeof file === 'string' ? file.trim() : DEFAULTS.file,
    nudgeDays: within(nudgeDays, 0, 30, DEFAULTS.nudgeDays),
    maxRows: within(maxRows, 1, 10, DEFAULTS.maxRows),
    tellClaude: typeof tellClaude === 'boolean' ? tellClaude : DEFAULTS.tellClaude,
    toasts: typeof toasts === 'boolean' ? toasts : DEFAULTS.toasts,
    marks: marks === 'plain' ? 'plain' : DEFAULTS.marks,
  }
}

