import type { Deadline } from '../types'

import { open, timeLeft } from './deadlines'

const DAY = 24 * 60 * 60_000

/** How near a deadline must be before working elsewhere is worth a word. */
export const NUDGE_MS = 3 * DAY

/** The thresholds a toast marks, in the order a deadline crosses them. */
export type Stage = '3d' | '1d' | 'overdue'

/** The last stage each deadline was toasted at, by id: what the store keeps. */
export type Toasted = Record<string, Stage>

const RANK: Record<Stage, number> = { '3d': 1, '1d': 2, overdue: 3 }

const SAYS: Record<Stage, string> = {
  '3d': 'is due in under 3 days',
  '1d': 'is due in under a day',
  overdue: 'is overdue',
}

/** A path as one spelling: forward slashes, no trailing one, lower case. */
const plain = (path: string) =>
  path.replace(/\\/g, '/').replace(/\/+$/, '').toLowerCase()

/** Whether `cwd` is one of the folders, or anywhere under one. */
export function isInside(paths: string[], cwd: string): boolean {
  const here = plain(cwd)

  return (
    here !== '' &&
    paths.some(path => {
      const root = plain(path)

      return root !== '' && (here === root || here.startsWith(`${root}/`))
    })
  )
}

/** The last name of a path: `reel-clips` of `C:\work\reel-clips`. */
export const folder = (cwd: string) => plain(cwd).split('/').pop() ?? ''

/**
 * The line for working in the wrong place: the soonest deadline inside the
 * threshold whose folders do not hold this session. `null` when there is
 * none, or when the session's own deadline is due sooner still.
 */
export function nudge(
  deadlines: Deadline[],
  now: number,
  cwd: string,
  withinMs = NUDGE_MS,
): string | null {
  if (cwd === '' || withinMs <= 0) {
    return null
  }

  for (const one of open(deadlines)) {
    if (one.dueAt - now >= withinMs) {
      return null
    }

    if (isInside(one.paths, cwd)) {
      return null
    }

    if (one.paths.length > 0) {
      const left = timeLeft(one.dueAt, now)
      const when = one.dueAt < now ? `is ${left}` : `is due in ${left}`

      return `${one.name} ${when}, and you are in ${folder(cwd)}`
    }
  }

  return null
}

function stage(dueAt: number, now: number): Stage | null {
  const left = dueAt - now

  return left < 0 ? 'overdue' : left < DAY ? '1d' : left < 3 * DAY ? '3d' : null
}

/**
 * What to toast now, and what to remember having toasted. A deadline is
 * named once for each threshold it crosses; one moved further away is
 * forgotten, so it is named again on its way back.
 */
export function thresholds(
  deadlines: Deadline[],
  now: number,
  seen: Toasted,
): { toasts: string[]; seen: Toasted } {
  const toasts: string[] = []
  const next: Toasted = {}

  for (const one of open(deadlines)) {
    const at = stage(one.dueAt, now)
    const before = seen[one.id]

    if (at === null) {
      continue
    }

    next[one.id] = at

    if (before === undefined || RANK[at] > RANK[before]) {
      toasts.push(`${one.name} ${SAYS[at]}`)
    }
  }

  return { toasts, seen: next }
}

/** What the store holds, read back as stages by id; anything else is none. */
export function readToasted(raw: unknown): Toasted {
  const seen: Toasted = {}

  if (typeof raw !== 'object' || raw === null) {
    return seen
  }

  for (const [id, value] of Object.entries(raw)) {
    if (value === '3d' || value === '1d' || value === 'overdue') {
      seen[id] = value
    }
  }

  return seen
}

/**
 * The section of the system prompt that tells Claude what is due. Days, not
 * hours, so the text changes once a day and the prompt cache holds.
 */
export function brief(
  deadlines: Deadline[],
  now: number,
  cwd: string,
): string | null {
  const rows = open(deadlines)

  if (rows.length === 0) {
    return null
  }

  const lines = rows.map(one => {
    const days = Math.floor(Math.abs(one.dueAt - now) / DAY)
    const left =
      one.dueAt < now
        ? `${days}d overdue`
        : days === 0
          ? 'due today'
          : `${days}d left`
    const next = one.next === null ? '' : `; next step: ${one.next}`
    const here = isInside(one.paths, cwd) ? '; this session is in its folder' : ''

    return `- ${one.id}: ${one.name}, due ${one.due} (${left})${next}${here}`
  })

  return [
    '# Deadlines',
    '',
    'The person tracks these deadlines with the due-band mod, which shows them above the prompt. Bring one up only when it bears on what they are doing. When they say a step is finished, a deadline is met, or a new one exists, update the list with the tools `mcp__due-band__set_next_step`, `mcp__due-band__mark_done` and `mcp__due-band__add_deadline` instead of editing the file.',
    '',
    ...lines,
  ].join('\n')
}

