/**
 * One entry of due.json, as written, with its dates also read into
 * milliseconds since the epoch.
 */
export type Deadline = {
  id: string
  name: string
  due: string
  dueAt: number
  start: string | null
  startAt: number | null
  next: string | null
  paths: string[]
  isDone: boolean
}

/** What the last read of due.json came to. */
export type Loaded = { deadlines: Deadline[]; error: string | null }

declare module 'claude-code' {
  interface PluginState {
    'due-band': {
      loaded: Loaded
      now: number
      isHidden: boolean
      /** The session's working folder at the last refresh; `''` before one. */
      cwd: string
      /** The wrong-project line this session already toasted; `''` for none. */
      nudged: string
    }
  }
}
